/* 无DOM的工单/隐患规则；每次在接口事务副本中运行。 */
(function(root){const copy=x=>JSON.parse(JSON.stringify(x));const check=(ok,msg)=>{if(!ok)throw new Error(msg);};const text=(x,label)=>check(typeof x==='string'&&x.trim()&&x.length<=2000,label+'必填且最多2000字');const key=r=>r.kind+':'+r.id;const manager=c=>['engineer','supervisor'].includes(c.role);const active=o=>!['closed','cancelled'].includes(o.status);
const problem=(data,ref)=>data[ref.kind]?.find(p=>p.id===ref.id);
function actions(kind,r,data,ctx){const a=[];if(kind==='work-orders'){if(manager(ctx)){if(r.status==='draft'&&r.createdBy!==ctx.person)a.push('approve');if(['approved','assigned'].includes(r.status))a.push('assign');if(r.status==='technical_complete'&&r.execution?.executorId!==ctx.person)a.push('accept');if(r.status==='accepted')a.push('close');if(active(r)&&r.status!=='accepted')a.push('cancel');}if(r.assigneeId===ctx.person&&['technician','contractor'].includes(ctx.role)){if(['assigned','paused'].includes(r.status))a.push('start');if(r.status==='executing')a.push('save','complete','pause');}}else if(kind==='hazards'){if(r.authority==='local'){if(['open','rectifying'].includes(r.status)&&(manager(ctx)||r.ownerId===ctx.person))a.push('submit');if(r.status==='pending_review'&&ctx.role==='safety'&&r.rectifierId!==ctx.person)a.push('review');}if(ctx.role==='safety'){if(r.authority==='local'&&['open','rectifying'].includes(r.status))a.push('assess');if(r.status!=='closed')a.push('control');if(r.status==='closed'&&r.restriction?.status==='active'&&r.rectifierId!==ctx.person)a.push('release');}if(r.authority==='EHS'&&ctx.role==='admin')a.push('sync');}return a;}
function needsResidual(outcome,p){if(p.status==='closed')return false;if(outcome.result==='resolved')return !(['pending_verification','restored','pending_review'].includes(p.status)||(p.authority==='EHS'&&p.pendingExternalReview));return true;}
function decorate(kind,r,data,ctx){const row=copy(r);row.actions=actions(kind,r,data,ctx);if(kind==='work-orders'){row.residualRequired=(r.execution?.outcomes||[]).filter(o=>needsResidual(o,problem(data,o))).map(o=>({kind:o.kind,id:o.id}));row.relatedProblems=r.problemRefs.map(ref=>({kind:ref.kind,...copy(problem(data,ref)||{id:ref.id,status:'missing'})}));}return row;}
function classified(data,h){check(!h.assessmentRequired&&typeof h.major==='boolean','须先由安全人员核实风险分类');check(!(h.authority==='local'&&h.major&&data.workConfig.hazardPolicy.majorRequiresExternal),'重大隐患须走权威治理流程');}
function safety(data,o,ctx){const staff=data.workConfig.executors.find(x=>x.id===o.assigneeId);check(staff&&staff.roles.includes(ctx.role)&&staff.equipmentIds.includes(o.equipmentId)&&Date.parse(staff.qualifiedUntil+'T23:59:59+08:00')>Date.now()&&ctx.scenario!=='qualification','作业资格失效或设备范围不符');const permit=data.workConfig.permits.find(p=>p.id===o.permitId);check(permit&&permit.status==='valid'&&permit.equipmentId===o.equipmentId&&permit.scopeType===o.scopeType&&Date.parse(permit.validUntil)>Date.now(),'作业许可无效、过期或范围不符');for(const ref of o.problemRefs.filter(x=>x.kind==='hazards')){const h=problem(data,ref);classified(data,h);check(h.control&&Date.parse(h.control.validUntil)>Date.now(),'关联隐患控制措施缺失或过期');}}
function command(data,ctx,kind,id,action,body){const affected=[];const now=new Date().toISOString();const list=kind==='work-orders'?data.workOrders:data.hazards;let row=list.find(x=>x.id===id);
if(!id){check(kind==='work-orders'&&manager(ctx),'无建单权限');text(body.reason,'建单原因');text(body.idempotencyKey,'幂等键');const memo=ctx.person+':work-order:'+body.idempotencyKey;const old=data.requests.find(r=>r.key===memo);if(old){check(old.payload===JSON.stringify(body),'幂等键与原请求不一致');return {record:list.find(o=>o.id===old.id),affected,unchanged:true};}text(body.title,'工单名称');text(body.scope,'工作范围');check(data.equipment.some(e=>e.id===body.equipmentId),'设备不存在');check(data.workConfig.scopeTypes.some(t=>t.id===body.scopeType),'专业范围无效');check(data.workConfig.permits.some(p=>p.id===body.permitId&&p.equipmentId===body.equipmentId&&p.scopeType===body.scopeType),'许可与设备专业范围不符');check(Array.isArray(body.problemRefs)&&body.problemRefs.length&&new Set(body.problemRefs.map(key)).size===body.problemRefs.length,'至少选择一个问题且不能重复');for(const ref of body.problemRefs){check(['defects','failures','hazards'].includes(ref.kind),'问题类型无效');const p=problem(data,ref);check(p&&p.equipmentId===body.equipmentId&&p.status!=='closed','问题不存在、跨设备或已经关闭');check(!list.some(o=>active(o)&&o.equipmentId===body.equipmentId&&o.scope.trim()===body.scope.trim()&&o.problemRefs.some(r=>key(r)===key(ref))),'同一问题同处置范围存在重复活动工单');}
row={id:'WO-'+(Math.max(2000,...list.map(o=>Number(o.id.split('-')[1])||0))+1),equipmentId:body.equipmentId,title:body.title.trim(),scope:body.scope.trim(),scopeType:body.scopeType,permitId:body.permitId,priority:body.problemRefs.some(r=>problem(data,r).priority==='high')?'high':body.problemRefs.some(r=>problem(data,r).priority==='medium')?'medium':'low',dueAt:body.dueAt||'',status:'draft',createdBy:ctx.person,createdAt:now,problemRefs:copy(body.problemRefs),executionVersion:0,execution:null,executionHistory:[],acceptances:[],version:1};list.push(row);data.requests.push({key:memo,id:row.id,payload:JSON.stringify(body)});return {record:row,affected};}
check(row,'记录不存在');check(Number(body.expectedVersion)===row.version,'版本冲突，请刷新比较');text(body.reason,'操作意见');
if(kind==='work-orders'){
if(action==='approve'){check(manager(ctx),'无审核权限');check(row.status==='draft','仅草稿可审核');check(row.createdBy!==ctx.person,'审核必须独立于建单人');row.status='approved';row.approvedBy=ctx.person;row.approvedAt=now;
}else if(action==='assign'){check(manager(ctx)&&['approved','assigned'].includes(row.status),'无派工权限或状态不允许');check(data.workConfig.executors.some(p=>p.id===body.assigneeId&&p.equipmentIds.includes(row.equipmentId)),'指派人员不具备设备范围资格');row.assigneeId=body.assigneeId;row.status='assigned';row.assignedAt=now;
}else if(action==='start'){check(row.assigneeId===ctx.person&&['technician','contractor'].includes(ctx.role),'非指派执行人员或无作业权限');check(['assigned','paused'].includes(row.status),'当前状态不能开工');safety(data,row,ctx);check(body.isolation===true&&body.guard===true,'必须逐项确认隔离与作业防护');if(row.status==='assigned'){row.executionVersion++;row.execution={revision:row.executionVersion,executorId:ctx.person,startedAt:now,diagnosis:'',measures:'',trial:'',laborMinutes:null,materialRef:'',outcomes:[]};}row.execution.safetySnapshot={permitId:row.permitId,isolation:true,guard:true,confirmedBy:ctx.person,confirmedAt:now};row.status='executing';row.reworkRequired=false;
}else if(['save','complete','pause'].includes(action)){check(row.assigneeId===ctx.person&&['technician','contractor'].includes(ctx.role),'非指派执行人员');check(row.status==='executing','当前状态不允许执行操作');if(action==='pause'){row.status='paused';row.pauseReason=body.reason;}else{safety(data,row,ctx);if(action==='complete'){text(body.diagnosis,'诊断');text(body.measures,'维修措施');text(body.trial,'试运行');check(Number.isFinite(Number(body.laborMinutes))&&Number(body.laborMinutes)>0,'实际工时须为正数');check(Array.isArray(body.outcomes)&&body.outcomes.length===row.problemRefs.length&&new Set(body.outcomes.map(key)).size===row.problemRefs.length,'每个关联问题必须提供唯一的逐项结果');for(const ref of row.problemRefs){const item=body.outcomes.find(r=>key(r)===key(ref));check(item,'逐项结果缺少关联问题');const p=problem(data,ref);check(Number(item.expectedProblemVersion)===p.version,'问题版本变化，请重新读取');check(['resolved','unresolved','not_applicable'].includes(item.result),'逐项结论无效');text(item.evidence,'逐项证据');if(item.result==='not_applicable')check(p.status==='closed','未关闭的问题不能判为不适用');if(item.result==='resolved')check(p.status!=='closed','问题已关闭，请说明不适用依据');if(ref.kind==='failures'&&item.result==='resolved')check(Number.isFinite(Date.parse(item.restoredAt))&&Date.parse(item.restoredAt)>=Date.parse(p.occurredAt)&&Date.parse(item.restoredAt)<=Date.now(),'故障恢复时间无效或早于失效');}}
Object.assign(row.execution,{diagnosis:body.diagnosis||'',measures:body.measures||'',trial:body.trial||'',laborMinutes:body.laborMinutes===''?null:Number(body.laborMinutes),materialRef:body.materialRef||'',outcomes:copy(body.outcomes||[]).map(x=>({...x,problemVersion:Number(x.expectedProblemVersion)}))});if(action==='complete'){row.execution.completedAt=now;row.executionHistory.push(copy(row.execution));row.status='technical_complete';}}
}else if(action==='accept'){check(row.execution?.executorId!==ctx.person,'必须由独立人员验收');check(manager(ctx),'无技术验收权限');check(row.status==='technical_complete','当前状态不能验收');check(['pass','return'].includes(body.decision),'验收决定无效');if(body.decision==='pass'){check(body.trialConfirmed===true,'必须确认试运行证据');for(const outcome of row.execution.outcomes){const p=problem(data,outcome);check(p&&p.version===outcome.problemVersion,'问题版本变化，技术验收不能覆盖');if(outcome.result==='resolved'){if(outcome.kind==='defects'){check(['open','in_progress'].includes(p.status),'缺陷已在其他验证流程');p.status='pending_verification';p.executorId=row.execution.executorId;}else if(outcome.kind==='failures'){check(p.status==='confirmed','故障已在其他恢复流程');p.status='restored';p.executorId=row.execution.executorId;p.restoredAt=outcome.restoredAt;}else if(p.authority==='local'){classified(data,p);check(['open','rectifying'].includes(p.status),'隐患已在其他复查流程');p.status='pending_review';p.rectifierId=row.execution.executorId;}else{p.pendingExternalReview=true;}p.evidence=outcome.evidence;p.version++;affected.push(p);}}row.status='accepted';}else{row.status='assigned';row.reworkRequired=true;}row.acceptances.push({executionVersion:row.executionVersion,reviewerId:ctx.person,decision:body.decision,reason:body.reason,reviewedAt:now});
}else if(action==='close'){check(manager(ctx)&&row.status==='accepted','无业务关闭权限或状态不允许');for(const ref of row.problemRefs){const p=problem(data,ref);check(!(ref.kind==='hazards'&&p.major&&p.status!=='closed'),'重大隐患尚未权威关闭，阻止工单关闭');}for(const outcome of row.execution.outcomes.filter(x=>needsResidual(x,problem(data,x)))){const p=problem(data,outcome);if(p.status==='closed')continue;check(!(outcome.kind==='hazards'&&p.major),'重大隐患残留阻止工单关闭');const arrangement=(body.residuals||[]).find(r=>key(r)===key(outcome));check(arrangement,'残留问题缺少后续安排');const followup=data.workOrders.find(o=>o.id===arrangement.followupOrderId);check(followup&&followup.id!==row.id&&active(followup)&&followup.status!=='draft'&&followup.approvedBy&&followup.problemRefs.some(r=>key(r)===key(outcome)),'后续必须是真实的同问题活动工单');check(data.people.some(p=>p.id===arrangement.ownerId),'后续责任人不存在');check(Number.isFinite(Date.parse(arrangement.dueAt))&&Date.parse(arrangement.dueAt+'T23:59:59+08:00')>Date.now(),'后续期限必填且不得过期');text(arrangement.control,'残留控制措施');check(Date.parse(arrangement.controlUntil)>=Date.parse(arrangement.dueAt+'T23:59:59+08:00'),'残留控制措施须覆盖后续期限');if(outcome.kind==='hazards')check(p.control&&Date.parse(p.control.validUntil)>=Date.parse(arrangement.dueAt+'T23:59:59+08:00'),'隐患原控制措施须有效覆盖后续期限');}row.residuals=copy(body.residuals||[]);row.closedBy=ctx.person;row.closedAt=now;row.status='closed';
}else if(action==='cancel'){check(manager(ctx)&&active(row)&&row.status!=='accepted','已验收工单须业务关闭；无终止权限或工单已关闭');if(row.executionVersion>0){check(body.siteRestored===true,'已开工须确认现场恢复');text(body.evidence,'终止现场证据');}row.status='cancelled';row.cancelReason=body.reason;
}else throw new Error('未知工单操作');
}else if(kind==='hazards'){
if(action==='sync'){check(ctx.role==='admin','仅集成评审角色可模拟权威回执');check(row.authority==='EHS','非外部权威隐患');const receipt=data.workConfig.externalReceipts.find(r=>r.id===body.receiptId&&r.externalId===row.externalId);check(receipt,'权威回执不存在或关联不符');if(receipt.externalVersion<=row.externalVersion)return {record:row,affected,unchanged:true};row.externalVersion=receipt.externalVersion;row.status=receipt.status;row.pendingExternalReview=false;row.authorityReceipt=copy(receipt);row.evidence=receipt.evidence;
}else if(action==='assess'){check(ctx.role==='safety','无风险核实权限');check(row.authority==='local'&&['open','rectifying'].includes(row.status),'当前隐患不能修改风险核实');check(['general','major'].includes(body.classification),'分类无效');text(body.evidence,'风险核实依据');row.major=body.classification==='major';row.assessmentRequired=false;row.assessment={classification:body.classification,basis:body.evidence,assessedBy:ctx.person,at:now};
}else if(action==='control'){check(ctx.role==='safety','无安全控制确认权限');text(body.evidence,'控制证据');text(body.control,'控制措施');check(Date.parse(body.validUntil)>Date.now(),'控制有效期无效或已过期');row.control={description:body.control,evidence:body.evidence,validUntil:body.validUntil,confirmedBy:ctx.person};
}else if(action==='release'){check(ctx.role==='safety'&&ctx.person!==row.rectifierId,'无独立安全放行权限');check(row.status==='closed'&&row.restriction?.status==='active','隐患未关闭或无活动限制');text(body.evidence,'放行证据');row.restriction={...row.restriction,status:'released',releasedBy:ctx.person,releasedAt:now,evidence:body.evidence};
}else{check(row.authority==='local','隐患由外部权威流程关闭，禁止本地审批');classified(data,row);if(action==='submit'){check(manager(ctx)||ctx.person===row.ownerId,'无整改提交权限');check(['open','rectifying'].includes(row.status),'当前状态不能提交复查');check(!row.assessmentRequired,'须先由安全人员核实风险分类');text(body.evidence,'整改证据');row.evidence=body.evidence;row.rectifierId=ctx.person;row.status='pending_review';}else if(action==='review'){check(ctx.role==='safety','无安全复查权限');check(row.status==='pending_review','当前状态不能复查');check(ctx.person!==row.rectifierId,'复查必须独立于整改人');check(['pass','return'].includes(body.decision),'复查决定无效');text(body.evidence,'复查证据');row.status=body.decision==='pass'?'closed':'rectifying';row.review={decision:body.decision,reason:body.reason,evidence:body.evidence,reviewerId:ctx.person,at:now};}else throw new Error('未知隐患操作');}}
row.version++;return {record:row,affected};}
const api={command,decorate,actions};if(typeof module==='object'&&module.exports)module.exports=api;else root.EamWorkRules=api;
})(typeof window==='undefined'?globalThis:window);
